function agricultureClimate(loc){
 const lat=Math.abs(Number(loc?.lat)||21),lon=Number(loc?.lon)||0,name=String(loc?.name||'');
 if(/السعودية|الإمارات|الكويت|قطر|البحرين|عُمان|الرياض|مكة|جدة|المدينة|الدمام|الدوحة|أبوظبي|دبي|مسقط/.test(name)||(lat>=15&&lat<=33&&lon>=30&&lon<=62))return {key:'arid',label:'مناخ حار جاف'};
 if(lat<15)return {key:'tropical',label:'مناخ مداري'};
 if(lat<35)return {key:'warm',label:'مناخ دافئ'};
 if(lat<55)return {key:'temperate',label:'مناخ معتدل'};
 return {key:'cool',label:'مناخ بارد'};
}
function agriProfile(crop,climate){return crop.seasons[climate.key]||crop.seasons.temperate||crop.seasons.warm||crop.seasons.arid;}
