 const line=chart.points.map((point,index)=>(index?'L':'M')+x(point.progress).toFixed(1)+' '+y(point.altitude).toFixed(1)).join(' ');
 path.setAttribute('d',line);area.setAttribute('d',line+' L 58 242 L 942 242 Z');
 const visible=chart.daylight&&Number.isFinite(chart.progress);marker.toggleAttribute('hidden',!visible);if(visible)marker.setAttribute('transform','translate('+x(chart.progress).toFixed(1)+' '+y(chart.sun.altitude).toFixed(1)+')');
 const state=!visible?(now<chart.start?'الشمس لم تشرق بعد':'الشمس غربت لهذا اليوم'):Math.abs(now-data.dhuhr)<10*60000?'الشمس قرب الزوال':now<data.dhuhr?'الشمس ترتفع قبل الزوال':'الشمس تنخفض بعد الزوال';
