function tick(){const now=new Date();if(L.dateISO(now,C.location.zone)!==todayKey||next&&now>=next.date)refresh();const secs=next?Math.max(0,Math.floor((next.date-now)/1000)):null,value=secs===null?'—':[Math.floor(secs/3600),Math.floor(secs%3600/60),secs%60].map(x=>arDigits(String(x).padStart(2,'0'))).join(':');text('#countdown',value);text('#devotionCountdown',value);all('.prayer-strip button').forEach((b,i)=>{b.classList.toggle('next',data.events[i].key===next?.key);b.classList.toggle('passed',!!data.events[i].date&&data.events[i].date<now);});if(enabled)for(const e of scheduled){if(!e.date||alertState[e.group]===false||alertState[e.key]===false)continue;const id=e.name+e.date.toISOString();if(now-e.date>=0&&now-e.date<60000&&!seen.has(id)){seen.add(id);notify(e.name,e.soundKey||e.key).then(sent=>{if(sent)C.save('calendar.sent',[...seen].slice(-100));else seen.delete(id);});}}}
