const camera=$('#cameraDialog');camera.innerHTML='<div class="live-heading"><h2>توثيق الظل والتحقق من الارتفاع</h2><button id="closeCamera">×</button></div><p>وجّه الكاميرا إلى الظل. لا تنظر إلى الشمس مباشرة.</p><video id="cameraVideo" autoplay playsinline muted></video><p id="cameraStatus" role="status"></p><button id="captureSun" class="primary-button">حفظ صورة</button><div class="live-fields"><label>ارتفاع الجسم الرأسي<input id="rodHeight" type="number" min="0.001" step="any" value="1"></label><label>طول الظل بنفس الوحدة<input id="shadowLength" type="number" min="0.001" step="any" value="1"></label></div><button id="measureShadow">قارن القياس بالحساب</button><p id="shadowResult" role="status"></p>';let stream=null,cameraRequest=0;
function stopCamera(){cameraRequest++;stream?.getTracks().forEach(t=>t.stop());stream=null;$('#cameraVideo').srcObject=null;}
all('.camera-shortcut').forEach(b=>b.onclick=async()=>{camera.showModal();text('#cameraStatus','جارٍ طلب إذن الكاميرا…');text('#shadowResult','');const request=++cameraRequest;try{if(!navigator.mediaDevices?.getUserMedia)throw Error();const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!camera.open||request!==cameraRequest){s.getTracks().forEach(t=>t.stop());return;}stream=s;$('#cameraVideo').srcObject=s;text('#cameraStatus','صورة مباشرة للتوثيق. قياس الظل أدناه يدوي.');}catch{text('#cameraStatus','لم تتوفر الكاميرا. يمكنك إدخال قياس الظل يدويًا.');}});$('#closeCamera').onclick=()=>camera.close();camera.addEventListener('close',stopCamera);camera.addEventListener('cancel',stopCamera);camera.addEventListener('click',e=>{if(e.target===camera)camera.close();});$('#captureSun').onclick=()=>{const v=$('#cameraVideo');if(!v.videoWidth){text('#cameraStatus','انتظر تشغيل الكاميرا قبل الالتقاط.');return;}const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(b=>{if(b)download(b,'shadow-'+Date.now()+'.jpg');},'image/jpeg',.92);};$('#measureShadow').onclick=()=>{const h=+$('#rodHeight').value,s=+$('#shadowLength').value;if(!(h>0&&s>0&&Number.isFinite(h)&&Number.isFinite(s))){text('#shadowResult','أدخل طولين موجبين وبالوحدة نفسها.');return;}const measured=Math.atan2(h,s)*180/Math.PI,expected=L.horizontal('Sun',new Date(),C.location).altitude;text('#shadowResult',expected<=0?'الشمس تحت الأفق بحسب الموقع والوقت؛ لا تصلح المقارنة الآن.':'الارتفاع من الظل '+fmt(measured)+'° • المحسوب '+fmt(expected)+'° • الفرق '+fmt(Math.abs(measured-expected))+'°. يتأثر القياس باستواء الأرض ورأسية الجسم ودقة الأطوال.');};
